import os
import json
from typing import Any, Dict, List, Optional, Union

import boto3


def _norm_bbox(block: Dict[str, Any]) -> Optional[Dict[str, float]]:
    geometry = block.get("Geometry") or {}
    bbox = geometry.get("BoundingBox")
    if not bbox:
        polygon = geometry.get("Polygon") or []
        if polygon:
            xs = [p.get("X", 0.0) for p in polygon if isinstance(p, dict)]
            ys = [p.get("Y", 0.0) for p in polygon if isinstance(p, dict)]
            if xs and ys:
                return {
                    "left": float(min(xs)),
                    "top": float(min(ys)),
                    "width": float(max(xs) - min(xs)),
                    "height": float(max(ys) - min(ys)),
                }
        return None
    return {
        "left": float(bbox.get("Left", 0.0)),
        "top": float(bbox.get("Top", 0.0)),
        "width": float(bbox.get("Width", 0.0)),
        "height": float(bbox.get("Height", 0.0)),
    }


def _extract_text(block: Dict[str, Any], blocks_by_id: Dict[str, Dict[str, Any]]) -> str:
    block_type = block.get("BlockType")
    if block_type == "WORD":
        return block.get("Text", "")
    if block_type == "LINE":
        return block.get("Text", "")
    if block_type in ("TABLE", "CELL"):
        texts: List[str] = []
        for rel in block.get("Relationships", []) or []:
            if rel.get("Type") == "CHILD":
                for child_id in rel.get("Ids", []) or []:
                    child = blocks_by_id.get(child_id)
                    if child:
                        child_text = _extract_text(child, blocks_by_id)
                        if child_text:
                            texts.append(child_text)
        return " ".join(texts).strip()
    return block.get("Text", "") or ""


def _build_response(blocks: List[Dict[str, Any]]) -> Dict[str, Any]:
    blocks_by_id = {b.get("Id"): b for b in blocks if b.get("Id")}
    output: Dict[str, Any] = {
        "blocks": [],
        "lines": [],
        "tables": [],
        "key_values": [],
        "pages": [],
    }

    page_map: Dict[int, Dict[str, Any]] = {}

    for block in blocks:
        block_type = block.get("BlockType")
        page_num = block.get("Page")

        item = {
            "id": block.get("Id"),
            "type": block_type,
            "text": _extract_text(block, blocks_by_id),
            "confidence": block.get("Confidence"),
            "bbox": _norm_bbox(block),
            "page": page_num,
        }

        output["blocks"].append(item)

        if page_num is not None:
            page_entry = page_map.setdefault(int(page_num), {"page": int(page_num), "lines": [], "tables": []})
            if block_type == "LINE":
                page_entry["lines"].append(item)
                output["lines"].append(item)
            elif block_type == "TABLE":
                page_entry["tables"].append(item)
                output["tables"].append(item)
            elif block_type in ("KEY_VALUE_SET",):
                output["key_values"].append(item)

    output["pages"] = [page_map[k] for k in sorted(page_map.keys())]
    return output


def extract_layout(
    file_path: Optional[str] = None,
    file_bytes: Optional[bytes] = None,
    bucket: Optional[str] = None,
    key: Optional[str] = None,
    features: Optional[List[str]] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Extract OCR and layout elements from a document using Amazon Textract.

    Input options:
      - file_path: local document path (PDF/JPG/PNG/TIFF)
      - file_bytes: in-memory bytes
      - bucket + key: S3 object location (uses textract analyze_document via S3 source not supported; kept for interface completeness)

    Returns a dict with blocks, lines, tables, key_values, and pages.
    """
    if features is None:
        features = ["TABLES", "FORMS"]

    textract = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))

    if file_bytes is None and file_path is None:
        raise ValueError("Provide either file_path or file_bytes.")

    if file_bytes is None:
        with open(file_path, "rb") as f:
            file_bytes = f.read()

    response = textract.analyze_document(
        Document={"Bytes": file_bytes},
        FeatureTypes=features,
    )

    blocks = response.get("Blocks", []) or []
    result = _build_response(blocks)
    result["provider"] = "amazon-textract"
    result["raw"] = response
    return result


def extract_layout_json(
    file_path: Optional[str] = None,
    file_bytes: Optional[bytes] = None,
    region_name: Optional[str] = None,
) -> str:
    return json.dumps(
        extract_layout(file_path=file_path, file_bytes=file_bytes, region_name=region_name),
        ensure_ascii=False,
        indent=2,
        default=str,
    )
